INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-004', 'Coda Wave', '2026-11-13', 'Llevo esperando más de 12 horas para ser atendido y esta no es una situación aislada: según lo que he visto y me han comentado, es algo que se repite todos los días en esta clínica. Lo más preocupante es que la clínica no está trabajando a…', 1, '8028500792533507') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
