INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-035', 'Felipe giaquinta', '2026-11-13', 'La peor experiencia en una guardia. Entramos a las 21 y nos fuimos a las 3 de la mañana. Tienen una sola medica de guardia a partir de las 00 que se encarga de todo. Nos mandaron a hacer radiografía y luego un tac. Y quienes se encargabab…', 1, '4140135940739697') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-035', 'Julia Vega', '2026-11-13', 'Estoy en la guardia desde las 15hs son las 19:48hs. Entre llamado y estudios mínimo una hora de espera para todo. Malos tratos de los administrativos de la entrada, la médica que me atendió, información débil y confusa de parte de la que me hizo la ecografía. LA ÚNICA QUE ME TRATÓ COMO UN SER HUMANO FUE LA ADMINISTRATIVA DEL SUBSUELO DE LABORATORIO Y LA CHICA DE LABORATORIO. El resto un desastre. En mi estadía ya escuché gente quejarse y llorar a los gritos 3 veces con la gente que labura acá que nada o muy poco han hecho para cambiar la situación de los pacientes. Una sola chica, que con su madre anciana y en silla de ruedas descompuesta del dolor, logró que la atendieran de emergencia (Después de una hora y media de espera con la madre descompuesta) porque pidió hablar con un superior. Se entiende que nadie gana bien, que el sistema está colapsado, que las guardias son larguísimas (Eso para los médicos nada más) Pero el trato humano no se puede dejar de lado nunca y menos cuando trabajas en un SANATORIO. Y no es la primera vez que sufro maltratos tanto de administrativos como de médicos de este sanatorio.
Media pila que nadie viene a un sanatorio por ganas y a pasarla bien y ustedes lo empeoran.', 1, '2984335131361934') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-035', 'Federico Sunsundegui', '2026-11-13', 'Lamentable la experiencia que tuve con el doctor Kilstein Jorge. Sin ganas de atender, no me dejo terminar de expresar como me sentía, sumado a eso me atendio 25 minutos tarde. No llegue a estar mas de 2 minutos en el consultorio. Si vas a la guardia te dicen que no es algo para atender ahi, pero vas con un medico clinico y tampoco tiene ganas de atenderte. Pesima experiencia para un paciente que esta yendo porque realmente se siente mal.', 1, '1614883846624983') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
