INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-043', 'Melanie pinto', '2026-11-13', 'Es la tercera vez que voy 1 vez por mi y 2 por pacientes adultos mayores en este caso vine por una ecografia y en la puerta dice adultos mayores entran en vompañia pero cuabdo fue el turno la señorita me nego el ingreso aunque en la puerta esta especificado y le dije que mi paciente le acaban de sacar sangre tiene 70 años y tiene dias sin probar alimentos porque esta vomitando y aun asi me nego el ingreso y solo sonrió y dijo qie cualquier cosa me avisaba en todo caso si va a ser asi deben sacar el cartel o renovarlo que sea a concepto del doctor que toca porque en anterior caso fui con mi mama de 72 años y era otro doctor y me dijo si pase. Los adultos mayores siempre entran acompañados', 3, '5650225935998163') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-043', 'Jhoss Lopez', '2026-11-13', 'Saque una cita en traumatologia con el dr Zela Acuña y la verdad muy mala atención... parecia que estaba mas apurado por irse que por atender bien. Mi otro reclamo es que yo necesitaba mi descanso medico para evitar descuento en mi trabajo. La consulta salio 42 soles, la hoja de "descanso medico" 20 soles y muy aparte tuve que pagar el llenado de dicha hoja a 52 soles...(muy aparte de los examenes y medicamentos recetados) me parece injusto tener que pagar ese monto para que escriban manualmente "letra ilegible" y lo registren en su sistema "virtual", lo cual ni lo rellenó bien porque no puso mi diagnóstico completo revelado x la ecografia y los dias de descanso dados por el doctor no compensan a lesión que tengo.', 2, '3521254743007456') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-043', 'Mayra Quispe Miranda', '2026-11-13', 'Yo tengo una niña de 3 años , antes de ir llame para ver si atendían a niños en el área de dermatología y la señorita me dijo que si , con toda la confianza me acerqué y todo bien con la dermatóloga que me mandó a hacer unos laboratorios,…', 2, '8722673098813963') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-043', 'Rosa Baldeon Alfaro', '2026-11-13', 'Falta de humanidad tenía a mi bb de 7 mese mal hasta vomito en el ''centro y simplemente no la atendían al final tuve que acudir al seguro cuando uno por la preocupación prefiere pagar por una atención estando la pediatra sin paciente no la atendió y era 12.20pm se supone que atienden hasta 1pm', 1, '9057395546329839') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
