INSERT INTO resenas (lead_id, autor, fecha, texto, estrellas, huella_texto) VALUES ('lead-real-059', 'Mauricio Mayta', '2026-11-13', 'Primero de todo:
La comida HORRIBLE, el peor pollo frito de todo Arequipa, el pollo crudo y parecía sancochado, las papas fritas  frías , saladas y aguadas.
Pedi unas alitas picantes , su salsa picante una porquería, en mi plato había una hoja de laurel, su salsa sin sabor y la textura parecía agua.
En el tema del "ambiente", deberían cambiar las mesas y sillas, son muy básicas e anticuadas.
Y en el tema del" servicio", no son nada atentos, muy descuidados y distraídos.

En fin un lugar que  nunca más volveré,le tenía  fé, pero me  llevé una  muy desagradable experiencia.', 1, '2832369601592158') ON CONFLICT (lead_id, huella_texto) DO NOTHING;
